code:
const mm = gsap.matchMedia();

mm.add("(min-width: 768px)", () => {
  // desktop only
  gsap.to(".box", { x: 300 });
});

mm.add("(max-width: 767px)", () => {
  // mobile only
  gsap.to(".box", { y: 100 });
});

mm.add("(prefers-reduced-motion: no-preference)", () => {
  // only for users who didn't ask for reduced motion
});

codeReact:
useGSAP(
  () => {
    const mm = gsap.matchMedia();
    mm.add("(min-width: 768px)", () => {
      gsap.to(".box", { x: 300 });
    });
    mm.add("(prefers-reduced-motion: no-preference)", () => {
      // motion that respects user settings
    });
  },
  { scope: container },
);
